// Concatenates the always-load-together CSS outputs into one file, hrifa.css,
// so every applet links a single stylesheet instead of remembering four in
// the right order. Run after `style-dictionary build` — base/light/dark must
// already exist on disk. fonts.css is deliberately NOT included: it's the
// one piece that's still legitimately opt-in per applet (see README.md).
import { readFileSync, writeFileSync } from "node:fs";

const PARTS = ["base.css", "light.css", "dark.css", "components.css"];
const DIR = "build/css/";

const banner = `/**\n * hrifa.css — generated by design-tokens/build-bundle.js, do not edit\n * directly. Concatenates ${PARTS.join(" + ")}\n * in that order. Edit one of those source files (or color-tokens.json,\n * for base/light/dark) and run \`npm run build\`, not this file.\n */\n\n`;

const bundled = banner + PARTS.map((name) => readFileSync(DIR + name, "utf8")).join("\n");

writeFileSync(DIR + "hrifa.css", bundled);
console.log(`hrifa.css written (${PARTS.join(" + ")})`);
